import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from 'jsr:@supabase/supabase-js@2';

const EXPO_PUSH_URL = 'https://exp.host/--/api/v2/push/send';

interface NotificationRequest {
  messageId: string;
  senderId: string;
  recipientIds: string[];
  subject: string;
  body: string;
}

Deno.serve(async (req: Request) => {
  try {
    // Only allow POST requests
    if (req.method !== 'POST') {
      return new Response(
        JSON.stringify({ error: 'Method not allowed' }),
        { status: 405, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Get the authorization header
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Missing authorization header' }),
        { status: 401, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Create Supabase client
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Parse request body
    const { messageId, senderId, recipientIds, subject, body }: NotificationRequest = await req.json();

    console.log('Sending notifications for message:', messageId);
    console.log('Recipients:', recipientIds);

    // Get sender information
    const { data: sender, error: senderError } = await supabase
      .from('profiles')
      .select('full_name')
      .eq('id', senderId)
      .single();

    if (senderError) {
      console.error('Error fetching sender:', senderError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch sender information' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Get push tokens for recipients who have notifications enabled
    const { data: recipients, error: recipientsError } = await supabase
      .from('profiles')
      .select('id, full_name, push_notifications_enabled')
      .in('id', recipientIds);

    if (recipientsError) {
      console.error('Error fetching recipients:', recipientsError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch recipients' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Filter recipients who have notifications enabled
    const enabledRecipientIds = recipients
      .filter(r => r.push_notifications_enabled)
      .map(r => r.id);

    if (enabledRecipientIds.length === 0) {
      console.log('No recipients have push notifications enabled');
      return new Response(
        JSON.stringify({ success: true, message: 'No notifications sent (all recipients have notifications disabled)' }),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Get push tokens for enabled recipients
    const { data: pushTokens, error: tokensError } = await supabase
      .from('push_tokens')
      .select('expo_push_token, user_id')
      .in('user_id', enabledRecipientIds)
      .eq('is_active', true);

    if (tokensError) {
      console.error('Error fetching push tokens:', tokensError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch push tokens' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    if (!pushTokens || pushTokens.length === 0) {
      console.log('No push tokens found for recipients');
      return new Response(
        JSON.stringify({ success: true, message: 'No push tokens found' }),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Prepare notification messages
    const messages = pushTokens.map(token => ({
      to: token.expo_push_token,
      sound: 'default',
      title: `New message from ${sender.full_name}`,
      body: subject,
      data: {
        messageId,
        senderId,
        type: 'new_message',
      },
      channelId: 'messages',
    }));

    console.log(`Sending ${messages.length} push notifications`);

    // Send push notifications to Expo
    const response = await fetch(EXPO_PUSH_URL, {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Accept-Encoding': 'gzip, deflate',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(messages),
    });

    const result = await response.json();
    console.log('Expo push notification result:', result);

    if (!response.ok) {
      console.error('Failed to send push notifications:', result);
      return new Response(
        JSON.stringify({ error: 'Failed to send push notifications', details: result }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify({ 
        success: true, 
        message: `Sent ${messages.length} notifications`,
        result 
      }),
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    console.error('Error in send-message-notification function:', error);
    return new Response(
      JSON.stringify({ error: error.message || 'Internal server error' }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
});

