// app/(tabs)/(home)/index.tsx
import React from "react";
import { FlatList, StyleSheet, View } from "react-native";
import { useTheme } from "@react-navigation/native";
import { modalDemos } from "@/components/homeData";
import { DemoCard } from "@/components/DemoCard";
import ReservationForm from "@/components/ReservationForm"; // Import the ReservationForm component

export default function HomeScreen() {
  const theme = useTheme();

  const data = [...modalDemos, { type: 'reservation' }]; // Add a reservation item to the data array

  const renderItem = ({ item }) => {
    if (item.type === 'reservation') {
      return <ReservationForm />; // Render the ReservationForm component
    } else {
      return <DemoCard item={item} />; // Render the DemoCard component
    }
  };

  return (
    <View style={[styles.container, { backgroundColor: theme.colors.background }]}>
      <FlatList
        data={data}
        renderItem={renderItem}
        keyExtractor={(item) => item.route || item.type} // Use item.type as key for reservation item
        contentContainerStyle={styles.listContainer}
        contentInsetAdjustmentBehavior="automatic"
        showsVerticalScrollIndicator={false}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  listContainer: {
    paddingTop: 48,
    paddingHorizontal: 16,
    paddingBottom: 100, // Extra padding for floating tab bar
  },
});
```

This code imports the `ReservationForm` component and adds it to the `FlatList`. The `renderItem` function checks the `type` of the item and renders the `ReservationForm` component if the type is 'reservation'.

